// Chest-relevant components are intentionally prioritized at the front.
const CHEST_FIRST_COMPONENTS = Object.freeze([
  Inventory,
  Interactable,
  NamedIdentity,
  Position,
]);

const KNOWN_COMPONENTS = Object.freeze([
  ...Object.values(Exported),
  Alignment,
  Brain,
  Collider,
  Damage,
  DoorState,
  Dungeon,
  DungeonLevel,
  DungeonLevelLink,
  DungeonState,
  Faction,
